INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('3af61f36-dfce-4b79-8689-efb1b133db07', 1, 'Empuje', '"1. Flexiones en pared/mesa: Apoyo alto, control del empuje.\n2. Rotaciones de brazos: Movilidad articular.\n3. Plancha en mesa: Cuerpo recto.\n4. Toques de hombro: De pie o apoyado, tocar hombro opuesto."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('3af61f36-dfce-4b79-8689-efb1b133db07', 2, 'Piernas', '"1. Sentadillas asistidas silla: Levántate y siéntate sin impulso.\n2. Marcha alta: Rodillas arriba.\n3. Elevación talones: Apoyado en pared.\n4. Pasos laterales: Ritmo constante."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('3af61f36-dfce-4b79-8689-efb1b133db07', 3, 'Core', '"1. Puente de glúteo: Boca arriba, eleva cadera.\n2. Plancha en rodillas: Mete el ombligo.\n3. Bicho muerto: Boca arriba, alternar toque de pie al suelo.\n4. Toques de talón: Crunch lateral."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('3af61f36-dfce-4b79-8689-efb1b133db07', 4, 'Descanso Activo', '"Misión de hoy: Salir a caminar 30 minutos a paso ligero o hacer 20 minutos de bicicleta. No te exijas, solo mantente en movimiento."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('3af61f36-dfce-4b79-8689-efb1b133db07', 5, 'Tirón', '"1. Remo c/ toalla: Tensión isométrica.\n2. Superman suave: Elevación leve de pecho.\n3. Retracción escapular: Junta omóplatos.\n4. Plancha invertida rodillas: Eleva cadera sentado."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('3af61f36-dfce-4b79-8689-efb1b133db07', 6, 'Full / HIIT', '"1. Marcha rápida.\n2. Sentadilla a silla.\n3. Flexiones en pared.\n4. Jumping jacks sin salto (pasos)."');
