INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('3af61f36-dfce-4b79-8689-efb1b133db07', 21, 'Empuje', '"1. Flexiones en pared/mesa: Apoyo alto, control del empuje.\n2. Rotaciones de brazos: Movilidad articular.\n3. Plancha en mesa: Cuerpo recto.\n4. Toques de hombro: De pie o apoyado, tocar hombro opuesto."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('6b6e611f-31e3-4985-a549-4cf7f356b91f', 1, 'Empuje', '"1. Flexiones regulares: Pecho a 2cm del suelo.\n2. Fondos: Baja cadera flexionando codos a 90°.\n3. Plancha c/ toques: Evita balancear la cadera.\n4. Flexiones diamante: Tríceps al fallo."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('6b6e611f-31e3-4985-a549-4cf7f356b91f', 2, 'Piernas', '"1. Sentadillas libres: Rompe el paralelo.\n2. Zancadas alternas: Rodilla casi toca el suelo.\n3. Sentadilla isométrica: Espalda a pared, 90°.\n4. Elevaciones talones: Lentas y controladas."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('6b6e611f-31e3-4985-a549-4cf7f356b91f', 3, 'Core', '"1. Plancha abdominal: Tensión total.\n2. Hollow body hold: Zona lumbar pegada al suelo.\n3. Escaladores: Velocidad máxima.\n4. Elevación de piernas: Control abdominal."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('6b6e611f-31e3-4985-a549-4cf7f356b91f', 4, 'Descanso Activo', '"Misión de hoy: Salir a caminar 30 minutos a paso ligero o hacer 20 minutos de bicicleta. No te exijas, solo mantente en movimiento."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('6b6e611f-31e3-4985-a549-4cf7f356b91f', 5, 'Tirón', '"1. Dominadas o Remo invertido: Pecho a la barra.\n2. Superman: Junta talones al subir.\n3. Plancha inversa: Cuerpo en línea recta.\n4. Remo isométrico toalla."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('6b6e611f-31e3-4985-a549-4cf7f356b91f', 6, 'Full / HIIT', '"1. Burpees: Pecho al piso.\n2. Sentadillas con salto.\n3. Flexiones dinámicas.\n4. Jumping Jacks."');
