INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('db8f4da2-ff41-45db-898b-951ff4c3242d', 1, 'Empuje', '"1. Press de Pecho (Máquina): Espalda pegada al asiento, empuje fluido.\n2. Press Militar (Mancuernas ligeras): Sentado, no arquees la espalda.\n3. Extensión Tríceps (Polea): Codos fijos a las costillas.\n4. Elevaciones Laterales (Mancuernas): Hasta la altura del hombro."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('db8f4da2-ff41-45db-898b-951ff4c3242d', 2, 'Piernas', '"1. Prensa de Piernas: Pies centrados, baja hasta 90°.\n2. Extensión Cuádriceps (Máquina): Sostén un segundo arriba.\n3. Curl de Isquios (Máquina): Acostado o sentado, movimiento controlado.\n4. Elevación Talones (Sentado en máquina)."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('db8f4da2-ff41-45db-898b-951ff4c3242d', 3, 'Core', '"1. Plancha en suelo: Apoyo antebrazos.\n2. Crunch en Máquina o Polea alta.\n3. Elevación Piernas (Silla Romana): Apoya antebrazos y sube rodillas.\n4. Rotación de Torso (Máquina)."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('db8f4da2-ff41-45db-898b-951ff4c3242d', 4, 'Descanso Activo', '"Misión de hoy: Salir a caminar 30 minutos a paso ligero o hacer 20 minutos de bicicleta. No te exijas, solo mantente en movimiento."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('db8f4da2-ff41-45db-898b-951ff4c3242d', 5, 'Tirón', '"1. Jalón al Pecho (Polea): Barra a la clavícula.\n2. Remo Sentado (Máquina): Jala al ombligo.\n3. Curl de Bíceps (Polea/Mancuerna): Aislamiento.\n4. Face Pull (Polea): Jala hacia los ojos separando codos."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('db8f4da2-ff41-45db-898b-951ff4c3242d', 6, 'Full / HIIT', '"1. 5 min Caminadora (Inclinación moderada).\n2. 5 min Elíptica (Ritmo base).\n3. 5 min Remo Ergómetro.\n4. 5 min Bici estática."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('db8f4da2-ff41-45db-898b-951ff4c3242d', 7, 'Empuje', '"1. Press de Pecho (Máquina): Espalda pegada al asiento, empuje fluido.\n2. Press Militar (Mancuernas ligeras): Sentado, no arquees la espalda.\n3. Extensión Tríceps (Polea): Codos fijos a las costillas.\n4. Elevaciones Laterales (Mancuernas): Hasta la altura del hombro."');
