INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('db8f4da2-ff41-45db-898b-951ff4c3242d', 21, 'Empuje', '"1. Press de Pecho (Máquina): Espalda pegada al asiento, empuje fluido.\n2. Press Militar (Mancuernas ligeras): Sentado, no arquees la espalda.\n3. Extensión Tríceps (Polea): Codos fijos a las costillas.\n4. Elevaciones Laterales (Mancuernas): Hasta la altura del hombro."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('b4a23b9e-da61-4956-a389-348d73b9bb06', 1, 'Empuje', '"1. Press de Banca (Barra): Retracción escapular, empuje explosivo.\n2. Press Militar (Barra o Mancuernas): Bloqueo arriba.\n3. Fondos en Máquina o Paralelas del gym.\n4. Cruces en Polea: Contracción máxima en el pecho."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('b4a23b9e-da61-4956-a389-348d73b9bb06', 2, 'Piernas', '"1. Sentadilla con Barra: Controla el descenso, rompe paralelo.\n2. Peso Muerto Rumano (Mancuernas o Barra): Flexión de cadera, tensión en isquios.\n3. Zancadas con Mancuernas: Caminando o estáticas.\n4. Prensa a 1 pierna (Unilateral)."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('b4a23b9e-da61-4956-a389-348d73b9bb06', 3, 'Core', '"1. Plancha Lastrada (Disco en espalda).\n2. Ab Wheel (Rueda abdominal): Descenso controlado.\n3. Rodillas al pecho colgado en barra.\n4. Crunch en Polea Alta pesado."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('b4a23b9e-da61-4956-a389-348d73b9bb06', 4, 'Descanso Activo', '"Misión de hoy: Salir a caminar 30 minutos a paso ligero o hacer 20 minutos de bicicleta. No te exijas, solo mantente en movimiento."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('b4a23b9e-da61-4956-a389-348d73b9bb06', 5, 'Tirón', '"1. Dominadas o Jalón al pecho pesado.\n2. Remo con Barra: Inclinación 45°.\n3. Curl Bíceps (Barra Z).\n4. Pájaros (Hombro Posterior en banco inclinado)."');
INSERT INTO public.reto_dias (reto_id, dia_numero, enfoque, rutina_json) VALUES ('b4a23b9e-da61-4956-a389-348d73b9bb06', 6, 'Full / HIIT', '"1. Clean & Press c/ Mancuernas.\n2. Kettlebell Swings.\n3. Burpees saltando al cajón.\n4. Sprints en Remo Ergómetro."');
